<?php
require __DIR__ . '/bootstrap.php'; require_admin(); $pdo = db();
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = (string)($_POST['action'] ?? '');
    try {
        if ($action === 'room') { $name = trim((string)$_POST['name']); if ($name === '') throw new RuntimeException(); $pdo->prepare('INSERT INTO rooms (name, location) VALUES (?, ?)')->execute([$name, trim((string)$_POST['location'])]); }
        elseif ($action === 'period') { $no = filter_input(INPUT_POST, 'period_no', FILTER_VALIDATE_INT); $label = trim((string)$_POST['label']); $start = $_POST['start_time'] ?? ''; $end = $_POST['end_time'] ?? ''; if (!$no || $label === '' || $start >= $end) throw new RuntimeException(); $pdo->prepare('INSERT INTO periods (period_no, label, start_time, end_time) VALUES (?, ?, ?, ?)')->execute([$no, $label, $start, $end]); }
        elseif ($action === 'user') { $username = trim((string)$_POST['username']); $name = trim((string)$_POST['full_name']); $password = (string)$_POST['password']; $role = $_POST['role'] === 'admin' ? 'admin' : 'teacher'; if ($username === '' || $name === '' || strlen($password) < 10) throw new RuntimeException(); $pdo->prepare('INSERT INTO users (username, full_name, password_hash, role, must_change_password) VALUES (?, ?, ?, ?, 1)')->execute([$username, $name, password_hash($password, PASSWORD_DEFAULT), $role]); }
        elseif ($action === 'reset_password') { $id = filter_input(INPUT_POST, 'user_id', FILTER_VALIDATE_INT); $password = (string)$_POST['password']; if (!$id || strlen($password) < 10) throw new RuntimeException(); $pdo->prepare('UPDATE users SET password_hash = ?, must_change_password = 1 WHERE id = ?')->execute([password_hash($password, PASSWORD_DEFAULT), $id]); }
        elseif ($action === 'toggle_user') { $id = filter_input(INPUT_POST, 'user_id', FILTER_VALIDATE_INT); if (!$id || $id === (int)current_user()['id']) throw new RuntimeException(); $pdo->prepare('UPDATE users SET active = NOT active WHERE id = ?')->execute([$id]); }
        elseif ($action === 'toggle_room') { $id = filter_input(INPUT_POST, 'room_id', FILTER_VALIDATE_INT); if (!$id) throw new RuntimeException(); $pdo->prepare('UPDATE rooms SET active = NOT active WHERE id = ?')->execute([$id]); }
        elseif ($action === 'toggle_period') { $id = filter_input(INPUT_POST, 'period_id', FILTER_VALIDATE_INT); if (!$id) throw new RuntimeException(); $pdo->prepare('UPDATE periods SET active = NOT active WHERE id = ?')->execute([$id]); }
        else { throw new RuntimeException(); }
        flash('success', '관리자 변경을 저장했습니다.');
    } catch (Throwable $error) { flash('error', '입력값을 확인하거나 중복 데이터를 확인하세요.'); }
    redirect('admin.php');
}
$users=$pdo->query('SELECT id, username, full_name, role, active, must_change_password FROM users ORDER BY role DESC, username')->fetchAll(); $rooms=$pdo->query('SELECT * FROM rooms ORDER BY name')->fetchAll(); $periods=$pdo->query('SELECT * FROM periods ORDER BY period_no')->fetchAll(); $reservations=$pdo->query('SELECT r.id, r.reservation_date, r.purpose, rm.name AS room_name, p.period_no, u.full_name FROM reservations r JOIN rooms rm ON rm.id=r.room_id JOIN periods p ON p.id=r.period_id JOIN users u ON u.id=r.user_id WHERE r.reservation_date >= CURDATE() ORDER BY r.reservation_date, p.period_no, rm.name LIMIT 100')->fetchAll();
layout_start('관리자');
?><h1>관리자 모드</h1><div class="admin-grid"><section class="card"><h2>사용자 추가</h2><form method="post"><input type="hidden" name="action" value="user"><label>아이디<input name="username" required></label><label>이름<input name="full_name" required></label><label>초기 비밀번호<input type="password" name="password" minlength="10" required></label><label>역할<select name="role"><option value="teacher">교사</option><option value="admin">관리자</option></select></label><?= csrf_field() ?><button>추가</button></form></section><section class="card"><h2>특별실 추가</h2><form method="post"><input type="hidden" name="action" value="room"><label>이름<input name="name" required></label><label>위치<input name="location"></label><?= csrf_field() ?><button>추가</button></form></section><section class="card"><h2>교시 추가</h2><form method="post"><input type="hidden" name="action" value="period"><label>교시 번호<input type="number" name="period_no" min="1" required></label><label>표시명<input name="label" required></label><label>시작<input type="time" name="start_time" required></label><label>종료<input type="time" name="end_time" required></label><?= csrf_field() ?><button>추가</button></form></section></div><section class="card"><h2>사용자</h2><table><tr><th>아이디</th><th>이름/역할</th><th>상태</th><th>관리</th></tr><?php foreach($users as $u): ?><tr><td><?=e($u['username'])?></td><td><?=e($u['full_name'])?> / <?=e($u['role'])?></td><td><?= $u['active'] ? '활성' : '중지' ?><?= $u['must_change_password'] ? ' · 비밀번호 변경 필요' : '' ?></td><td><form method="post" class="inline"><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><?= csrf_field() ?><button><?= $u['active'] ? '중지' : '활성' ?></button></form><form method="post" class="inline"><input type="hidden" name="action" value="reset_password"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><input type="password" name="password" minlength="10" placeholder="새 비밀번호" required><?= csrf_field() ?><button>초기화</button></form></td></tr><?php endforeach; ?></table></section><section class="card"><h2>특별실 / 교시</h2><table><tr><th>특별실</th><th>상태</th><th></th></tr><?php foreach($rooms as $r): ?><tr><td><?=e($r['name'])?> <?=e($r['location'])?></td><td><?= $r['active'] ? '활성' : '중지' ?></td><td><form method="post"><input type="hidden" name="action" value="toggle_room"><input type="hidden" name="room_id" value="<?= (int)$r['id'] ?>"><?= csrf_field() ?><button><?= $r['active'] ? '중지' : '활성' ?></button></form></td></tr><?php endforeach; ?></table><table><tr><th>교시</th><th>시간</th><th>상태</th><th></th></tr><?php foreach($periods as $p): ?><tr><td><?=e($p['period_no'])?>교시 <?=e($p['label'])?></td><td><?=e(substr($p['start_time'],0,5))?>–<?=e(substr($p['end_time'],0,5))?></td><td><?= $p['active'] ? '활성' : '중지' ?></td><td><form method="post"><input type="hidden" name="action" value="toggle_period"><input type="hidden" name="period_id" value="<?= (int)$p['id'] ?>"><?= csrf_field() ?><button><?= $p['active'] ? '중지' : '활성' ?></button></form></td></tr><?php endforeach; ?></table></section><section class="card"><h2>예정 예약 (최대 100건)</h2><table><tr><th>날짜</th><th>특별실</th><th>교시</th><th>교사</th><th>목적</th><th>관리</th></tr><?php foreach($reservations as $reservation): ?><tr><td><?=e($reservation['reservation_date'])?></td><td><?=e($reservation['room_name'])?></td><td><?=e($reservation['period_no'])?>교시</td><td><?=e($reservation['full_name'])?></td><td><?=e($reservation['purpose'])?></td><td><form method="post" action="reservation_cancel.php"><input type="hidden" name="reservation_id" value="<?= (int)$reservation['id'] ?>"><?= csrf_field() ?><button class="danger">관리자 취소</button></form></td></tr><?php endforeach; ?></table></section><?php layout_end();

